static double chelis_cr_exp__as_exp_accurate(double x){
  static const double ch[][2] =
    {{0x1p+0, 0}, {0x1p-1, 0x1.712f72ecec2cfp-99}, {0x1.5555555555555p-3, 0x1.5555555554d07p-57},
     {0x1.5555555555555p-5, 0x1.55194d28275dap-59}, {0x1.1111111111111p-7, 0x1.12faa0e1c0f7bp-63},
     {0x1.6c16c16da6973p-10, -0x1.4ba45ab25d2a3p-64}, {0x1.a01a019eb7f31p-13, -0x1.9091d845ecd36p-67}};
  chelis_cr_exp__b64u64_u ix = {.f = x};
  if(__builtin_expect(((ix.u>>52)&0x7ff)<0x3c9, 0)) return 1 + x;
  const double s = 0x1.71547652b82fep+12;
  double t = chelis_cr_exp__roundeven_finite(x*s);
  chelis_cr_exp__i64 jt = t, i0 = (jt>>6)&0x3f, i1 = jt&0x3f, ie = jt>>12;
  double t0h = chelis_cr_exp__t0[i0][1], t0l = chelis_cr_exp__t0[i0][0];
  double t1h = chelis_cr_exp__t1[i1][1], t1l = chelis_cr_exp__t1[i1][0];
  double tl, th = chelis_cr_exp__muldd(t0h,t0l, t1h,t1l, &tl);

  /* Use Cody-Waite argument reduction: since |x| < 745, we have |t| < 2^23,
     thus since l2h is exactly representable on 29 bits, l2h*t is exact. */
  const double l2h = 0x1.62e42ffp-13, l2l = 0x1.718432a1b0e26p-47, l2ll = 0x1.9ff0342542fc3p-102;
  double dx = x - l2h*t, dxl = l2l*t, dxll = l2ll*t + __builtin_fma(l2l,t,-dxl);
  double dxh = dx + dxl; dxl = (dx - dxh) + dxl + dxll;
  double fl, fh = chelis_cr_exp__opolydd(dxh,dxl, 7,ch, &fl);
  fh = chelis_cr_exp__muldd(dxh,dxl, fh,fl, &fl);
  if(__builtin_expect(ix.u>0xc086232bdd7abcd2ull, 0)){
    // x < -0x1.6232bdd7abcd2p+9
    ix.u = (1-ie)<<52;
    fh = chelis_cr_exp__muldd(fh,fl, th,tl, &fl);
    fh = chelis_cr_exp__fastsum(th,tl, fh,fl, &fl);
    double e;
    fh = chelis_cr_exp__fasttwosum(ix.f, fh, &e);
    fl += e;
    fh = chelis_cr_exp__as_todenormal(fh + fl);
  } else {
    if(th == 1.0){
      double e;
      fh = chelis_cr_exp__fasttwosum(th,fh, &e);
      fl = chelis_cr_exp__fasttwosum(e, fl, &e);
      ix.f = fl;
      if((ix.u&(~(chelis_cr_exp__u64)0>>12))==0) {
	chelis_cr_exp__b64u64_u v = {.f = e};
	chelis_cr_exp__i64 d = ((chelis_cr_exp__u64)(((chelis_cr_exp__i64)ix.u>>63)^((chelis_cr_exp__i64)v.u>>63))<<1) + 1;
	ix.u += d;
	fl = ix.f;
      }
    } else {
      fh = chelis_cr_exp__muldd(fh,fl, th,tl, &fl);
      fh = chelis_cr_exp__fastsum(th,tl, fh,fl, &fl);
    }
    fh = chelis_cr_exp__fasttwosum(fh,fl, &fl);
    ix.f = fl;
    chelis_cr_exp__u64 d = (ix.u + 2)&(~(chelis_cr_exp__u64)0>>12);
    if(__builtin_expect(d<=2, 0)) fh = chelis_cr_exp__as_exp_database(x, fh);
    fh = chelis_cr_exp__as_ldexp(fh, ie);
  }
  return fh;
}

static double chelis_cr_exp__cr_exp(double x){
  chelis_cr_exp__b64u64_u ix = {.f = x};
  chelis_cr_exp__u64 aix = ix.u & (~(chelis_cr_exp__u64)0>>1);
  // exp(x) rounds to 1 to nearest for |x| <= 0x1p-54
  if(__builtin_expect(aix <= 0x3c90000000000000ull, 0)) // |x| <= 0x1p-54
    return 1.0 + x;
  if(__builtin_expect(aix>=0x40862e42fefa39f0ull, 0)){ // |x| >= 0x1.62e42fefa39fp+9
    if(aix>0x7ff0000000000000ull) return x + x; // nan
    if(aix==0x7ff0000000000000ull){ // |x| = inf
      if(ix.u>>63)
	return 0.0; // x = -inf
      else
	return x; // x = inf
    }
    if(!(ix.u>>63)){ // x >= 0x1.62e42fefa39fp+9
      volatile double z = 0x1p1023;
      return z*z;
    }
    if (aix>=0x40874910d52d3052ull) { // x <= -0x1.74910d52d3052p+9
      volatile double z = 0x1p-1022;
      return z * z;
    }
  }
  const double s = 0x1.71547652b82fep+12;
  double t = chelis_cr_exp__roundeven_finite(x*s);
  chelis_cr_exp__i64 jt = t, i0 = (jt>>6)&0x3f, i1 = jt&0x3f, ie = jt>>12;
  double t0h = chelis_cr_exp__t0[i0][1], t0l = chelis_cr_exp__t0[i0][0];
  double t1h = chelis_cr_exp__t1[i1][1], t1l = chelis_cr_exp__t1[i1][0];
  double tl, th = chelis_cr_exp__muldd(t0h,t0l, t1h,t1l, &tl);
  const double l2h = 0x1.62e42ffp-13, l2l = 0x1.718432a1b0e26p-47;
  /* Use Cody-Waite argument reduction: since |x| < 745, we have |t| < 2^23,
     thus since l2h is exactly representable on 29 bits, l2h*t is exact. */
  double dx = (x - l2h*t) + l2l*t, dx2 = dx*dx;
  // |dx| < log(2)/2^13 (experimentally)
  /* 1 + x*(c0 + c1*x + ... + c3*x^3) is a degree-4 approximation of exp(x)
     on [-log(2)/2^13,log(2)/2^13] with absolute error bounded by 2^-76.173
     according to Sollya */
  static const double ch[] = {0x1p+0, 0x1p-1, 0x1.55555557e54ffp-3,
                              0x1.55555553a12f4p-5};
  double p = (ch[0] + dx*ch[1]) + dx2*(ch[2] + dx*ch[3]);
  double fh = th, tx = th*dx, fl = tl + tx*p;
  double eps = 1.64e-19;
  if(__builtin_expect(ix.u>0xc086232bdd7abcd2ull, 0)){
    // subnormal case: x < -0x1.6232bdd7abcd2p+9
    ix.u = (1-ie)<<52;
    double e;
    fh = chelis_cr_exp__fasttwosum(ix.f, fh, &e);
    fl += e;
    double ub = fh + (fl + eps), lb = fh + (fl - eps);
    if (__builtin_expect(ub != lb, 0)) return chelis_cr_exp__as_exp_accurate(x);
    fh = chelis_cr_exp__as_todenormal(lb);
  } else {
    double ub = fh + (fl + eps), lb = fh + (fl - eps);
    if(__builtin_expect( ub != lb, 0)) return chelis_cr_exp__as_exp_accurate(x);
    fh = chelis_cr_exp__as_ldexp(lb, ie);
  }
  return fh;
}

static double chelis_cr_exp(double x) {
  double y = chelis_cr_exp__cr_exp(x);
  return y != y ? chelis_cr_canonical_nan() : y;
}

