#include <stdint.h>
#include <inttypes.h>

// Warning: clang also defines __GNUC__
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic ignored "-Wunknown-pragmas"
#endif


typedef unsigned __int128 chelis_cr_sin__u128;

typedef uint64_t chelis_cr_sin__u64;

typedef union {
  double f;
  uint64_t u;
} chelis_cr_sin__f64_u;

// round (-1)^sbit*r/2^128 to double, assuming r is non-zero and not in the
// subnormal region
static inline double chelis_cr_sin__u128_tod (chelis_cr_sin__u128 r, int sbit)
{
  uint64_t h = r >> 64, l = r;
  uint64_t sh = (h != 0) ? __builtin_clzll (h) : 64 + __builtin_clzll (l);
  h = r >> (75 - sh); // upper 53 non-zero bits
  int rbit = (r >> (74 - sh)) & 1; // round bit
  static const double Sgn[] = { 0x1p-53, -0x1p-53 };
  chelis_cr_sin__f64_u v = {.f = Sgn[sbit]};
  v.u -= sh << 52; // scale by 2^-sh
  double a = h * v.f, b = a * ((rbit) ? 0x1p-53 : 0x1p-54);
  return a + b;
}

typedef union {double f; uint64_t u;} chelis_cr_sin__b64u64_u;

/* This table approximates 1/(2pi) downwards with precision 1280:
   1/(2*pi) ~ T[0]/2^0 + T[1]/2^64 + ... + T[i]/2^(i*64) + ...
   Computed with computeT() from sin.sage, and manually added entry 0. */
static const uint64_t chelis_cr_sin___T[20] = {
  0,
  0x28be60db9391054a, // i=1
   0x7f09d5f47d4d3770,
   0x36d8a5664f10e410,
   0x7f9458eaf7aef158,
   0x6dc91b8e909374b8,
   0x1924bba82746487, // i=6
   0x3f877ac72c4a69cf,
   0xba208d7d4baed121,
   0x3a671c09ad17df90,
   0x4e64758e60d4ce7d,
   0x272117e2ef7e4a0e, // i=11
   0xc7fe25fff7816603,
   0xfbcbc462d6829b47,
   0xdb4d9fb3c9f2c26d,
   0xd3d18fd9a797fa8b,
   0x5d49eeb1faf97c5e, // i=16
   0xcf41ce7de294a4ba,
   0x9afed7ec47e35742,
   // 0x1580cc11bf1edaea, // i=19 (only used in reduce_large_acc)
   // 0xfc33ef0826bd0d87, // i=20 (unused)
};

#define chelis_cr_sin__U128(l,h) (((chelis_cr_sin__u128)h)<<64 | (chelis_cr_sin__u128)l) // little endian

/* The following is a degree-7 polynomial with odd coefficients
   approximating sin(x) for 0 <= x < 2^-11.348 with absolute error
   < 2^-128.601. Coefficients of degree 1, 3, 5 are PS[i]/2^128,
   with that of degree 7 is PS[i]/2^64 (fixed point).
   Generated with sinlarge_acc.sollya. */
