// accurate path for |x| >= 2^31
static double 
chelis_cr_sin__sin_large_accurate (double x)
{
  chelis_cr_sin__u128 r;
  int neg;
  uint64_t k = chelis_cr_sin__reduce_large_acc (&r, &neg, x);

  // twopi/2^128 approximates 2pi/2^3
  static const chelis_cr_sin__u128 twopi = chelis_cr_sin__U128(0xc4c6628b80dc1cd1,0xc90fdaa22168c234);
  r = chelis_cr_sin__mhUU(twopi, r << 3); // replace r by 2pi*r
  chelis_cr_sin__u128 u2 = chelis_cr_sin__mhUU(r,r), u4 = chelis_cr_sin__mhUU(u2,u2), u2h = u2 >> 64;

  /* x/(2*pi) mod 1 = k/2^13 + r + eps with |r| <= 2^-14 and 0 <= eps < 2^-127.999
     then sin(x) ~ sin(pi*k/2^12 + 2*pi*r)
                 ~ sin(pi*k/2^12)*cos(2*pi*r) + cos(pi*k/2^12)*sin(2*pi*r)
     Write k = 2^12*s + 2^6*i1 + i2 and t1=pi*i1/2^6, t2 = pi*i2/2^12
     then sin(pi*k/2^12) = (-1)^s*[sin(t1)*cos(t2)+cos(t1)*sin(t2)]
     and  cos(pi*k/2^12) = (-1)^s*[cos(t1)*cos(t2)-sin(t1)*sin(t2)]
  */
  int sbit = (x > 0) ? 0 : 1;
  sbit = sbit ^ (k >> 12);
  int i1 = (k >> 6) & 0x3f, i2 = k & 0x3f;

  chelis_cr_sin__u128 s1u, c1u, t;
  // approximate |sin(z)| in s1u/2^128
  chelis_cr_sin__u128 s1 = (i1 <= 32) ? chelis_cr_sin__S1u[i1] : chelis_cr_sin__S1u[64-i1]; // use sin(pi-x) = sin(x)
  // since cos(x) = sin(x+pi/2), we have |C1u[i1]| = |S1u[(i1+32) mod 64]|
  chelis_cr_sin__u128 c1 = (i1 <= 32) ? chelis_cr_sin__S1u[32-i1] : chelis_cr_sin__S1u[i1-32];
  s1u = chelis_cr_sin__mhUU (s1, chelis_cr_sin__C2u[i2]);
  t = chelis_cr_sin__mhUU (c1, chelis_cr_sin__S2u[i2]);
  // if i1 >= 32, we have to subtract t
  /* s1u/2^128 approximates sin(t1)*cos(t2), and t/2^128 approximates (up to sign)
     sin(t2)*cos(t1), thus s1u +/- t approximates sin(z=t1+t2), but since
     sin(z) >= 0 (0 <= z < pi), we have s1u +/- t >= 0. */
  s1u = (i1 < 32) ? s1u + t : s1u - t;

  // approximate cos(z) in c1u/2^128
  c1u = chelis_cr_sin__mhUU (c1, chelis_cr_sin__C2u[i2]);
  t = chelis_cr_sin__mhUU (s1, chelis_cr_sin__S2u[i2]);
  c1u = (i1 < 32) ? c1u - t : c1u + t;

  chelis_cr_sin__u128 Sr = chelis_cr_sin__evalPS (r, u2, u2h, u4); // Sr/2^128 approximates |sin(2*pi*r)|
  chelis_cr_sin__u128 Cr = chelis_cr_sin__evalPC (u2, u2h, u4);    // Cr/2^128 approximates cos(2*pi*r)

  // now combine: sin(x) ~ s1*C + c1*S
  s1u = chelis_cr_sin__mhUU(s1u,Cr);
  c1u = chelis_cr_sin__mhUU(c1u,Sr);

  /* s1u/2^128 approximates sin(z)*cos(r) which is always >= 0, while
     c1u/2^128 approximates cos(z)*sin(r), where cos(z) > 0 for i1 < 32,
     and cos(z) <= for i1 >= 32, and sign(r) has the sign of r. */
  if ((i1 < 32) ^ neg) // r >= 0
    s1u += c1u;
  else if (s1u < c1u) {
    s1u = c1u - s1u;
    sbit ^= 1;
  } else
    s1u = s1u - c1u;
  return chelis_cr_sin__u128_tod (s1u, sbit);
}

// accurate path for |x| < 2^-16
static inline double
chelis_cr_sin__sin_small_accurate (double x)
{
  /* x + (c3h+c3l)*x^3 + c5*x^5 approximates sin(x) on [0,2^-16] with relative
     error < 2^-112.743, cf sinsmall_acc.sollya */
  static const double c3h = -0x1.5555555555555p-3, c3l = -0x1.55554b00de7e8p-57,
    c5 = 0x1.111111110848p-7;
  double h, l, t, x2h = x * x, x2l = __builtin_fma (x, x, -x2h);
  h = c5 * x2h; // relative error less than ulp(c5*x^4)/ulp(x) ~ 2^-123
  h += c3l;     // relative error less than ulp(c3l*x^2)/ulp(x) ~ 2^-141
  h = chelis_cr_sin__fasttwosum (c3h, h, &l);
  h = chelis_cr_sin__muldd (h, l, x2h, x2l, &l);
  h = chelis_cr_sin__muldd (h, l, x, 0, &l);
  h = chelis_cr_sin__fasttwosum (x, h, &t);
  l += t;
  return h + l;
}

// fast path for 0x1.7137449123ef6p-26 < |x| < 2^31
// ax = |x| and eps is the error bound for the rounding test
// see proof of correctness in sin.pdf
static inline double
chelis_cr_sin__cr_sin_moderate (double x, int sbit)
{
  double ax = __builtin_fabs(x);
  static const double invpi = 0x1.45f306dc9c883p+12;
  // |invpi/2^14 - 1/pi| < 2^-55.496
  double k = __builtin_roundeven (invpi * ax);
  // |2^14*(pih + pil) + pi| < 2^-108.041
  double rh = __builtin_fma (k, chelis_cr_sin__pih, ax), rl = k * chelis_cr_sin__pil; // rh is exact

  double r = rh + rl; // |r| < 2^-13.339 (see sin.pdf)
  double r2 = r * r;
  int64_t j = k;
  sbit ^= (j >> 14) & 1; // reduction by an odd multiple of pi?
  int i1 = (j >> 7) & 0x7f, i2 = j & 0x7f;
  double s1h, s1l, s2h, s2l;
  s1h = chelis_cr_sin__muldd (chelis_cr_sin__U1[i1][0], chelis_cr_sin__U1[i1][1], chelis_cr_sin__U2[i2][2], chelis_cr_sin__U2[i2][3], &s1l);
  s2h = chelis_cr_sin__muldd (chelis_cr_sin__U2[i2][0], chelis_cr_sin__U2[i2][1], chelis_cr_sin__U1[i1][2], chelis_cr_sin__U1[i1][3], &s2l);
  double Sh, Sl;
  Sh = chelis_cr_sin__fastsum (s1h, s1l, s2h, s2l, &Sl);
  double Ch = chelis_cr_sin__U1[i1][2] * chelis_cr_sin__U2[i2][2] - chelis_cr_sin__U1[i1][0] * chelis_cr_sin__U2[i2][0];

  /* for |r| <= 2^-13.339, the polynomial r - 0x1.55555553068fp-3 * r^3
     approximates sin(r) with absolute error < 2^-76.494, and the polynomial
     -0.5 * r^2 + 0x1.55555553bfd3p-5 * r^4 approximates cos(r)-1 with
     absolute error < 2^-92.723 (cf sinmoderate.sollya) */
  double sh =  r * ( 1.0 - 0x1.55555553068fp-3 * r2);
  double ch = r2 * (-0.5 + 0x1.55555553bfd3p-5 * r2);
  double fh = Sh, fl = Sl + Sh*ch + Ch*sh;
  static const double Sgn[] = {1.0, -1.0};
  const double eps = 0x1.dep-64, eps2 = 0x1.dep-63;
  fh = Sgn[sbit] * fh;
  fl = Sgn[sbit] * fl - eps;
  double lb = fh + fl, ub = fh + (fl + eps2);
  if (__builtin_expect (ub == lb, 1)) return lb;
  if (__builtin_fabs (x) < 0x1p-16) return chelis_cr_sin__sin_small_accurate (x);
  return chelis_cr_sin__sin_large_accurate (x);
}

// fast path for |x| >= 2^31
// ax = |x| and eps is the error bound for the rounding test
static double 
chelis_cr_sin__cr_sin_large (double x)
{
  double ax = __builtin_fabs(x);
  double r;
  uint64_t j = chelis_cr_sin__reduce_large (&r, ax);
  // now x/(2pi) ~ k + j/2^15 + r with 0 <= r < 2^-15
  int sbit = (x > 0) ? 0 : 1;

  double r2 = r * r;
  sbit = sbit ^ (j >> 14); // reduction by an odd multiple of pi?
  int i1 = (j >> 7) & 0x7f, i2 = j & 0x7f;
  double s1h, s1l, s2h, s2l;
  s1h = chelis_cr_sin__muldd (chelis_cr_sin__U1[i1][0], chelis_cr_sin__U1[i1][1], chelis_cr_sin__U2[i2][2], chelis_cr_sin__U2[i2][3], &s1l);
  s2h = chelis_cr_sin__muldd (chelis_cr_sin__U2[i2][0], chelis_cr_sin__U2[i2][1], chelis_cr_sin__U1[i1][2], chelis_cr_sin__U1[i1][3], &s2l);
  double Sh, Sl;
  Sh = chelis_cr_sin__fastsum (s1h, s1l, s2h, s2l, &Sl);
  double Ch = chelis_cr_sin__U1[i1][2] * chelis_cr_sin__U2[i2][2] - chelis_cr_sin__U1[i1][0] * chelis_cr_sin__U2[i2][0];

  double sh = r * (0x1.921fb54442d18p2 - 0x1.4abbcdb6b26d1p5 * r2);
  double ch = r2 * (-0x1.3bd3cc9be45dep4 + 0x1.03c1eee483083p6 * r2);
  double fh = Sh, fl = Sl + Sh*ch + Ch*sh;
  static const double Sgn[] = {1.0, -1.0};
  fh = Sgn[sbit] * fh;
  fl = Sgn[sbit] * fl;
  // fails with eps=0x1.7fp-64 and x=0x1.54a9ad28f0a25p+225 (rndz, no FMA)
  static const double eps = 0x1.01p-63;
  double lb = fh + (fl - eps), ub = fh + (fl + eps);
  if (__builtin_expect (lb == ub, 1)) return lb;
  return chelis_cr_sin__sin_large_accurate (x);
}

static double
chelis_cr_sin__cr_sin (double x)
{
  chelis_cr_sin__b64u64_u t = {.f = x};
  // deal with tiny x to avoid underflow
  uint64_t au = t.u<<1;
  if (__builtin_expect(au <= 0x7cae26e892247decull, 0)) {
    // |x| <= 0x1.7137449123ef6p-26
    if (au == 0) return x;
    // Taylor expansion of sin(x) is x - x^3/6 around zero
    // for x=-0, fma (x, -0x1p-54, x) returns +0
    /* We have underflow when 0 < |x| < 2^-1022 or when |x| = 2^-1022
       and rounding towards zero. */
    double res = __builtin_fma (x, -0x1p-54, x);
    return res;
  }
  int e = (t.u>>52)&0x7ff;
  if (__builtin_expect(e < 1054, 1)) return chelis_cr_sin__cr_sin_moderate(x, t.u>>63); // |x| < 2^31
  if (__builtin_expect (e == 0x7ff, 0)) /* NaN, +Inf and -Inf. */
    {
      return x - x; // raises invalid
    }
  // now |x| >= 2^31
  return chelis_cr_sin__cr_sin_large (x);
}

static double chelis_cr_sin(double x) {
  double y = chelis_cr_sin__cr_sin(x);
  return y != y ? chelis_cr_canonical_nan() : y;
}

