#include <stdint.h>

// Warning: clang also defines __GNUC__
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic ignored "-Wunknown-pragmas"
#endif


typedef union {double f; uint64_t u;} chelis_cr_atan__b64u64_u;
typedef uint64_t chelis_cr_atan__u64;

static inline double chelis_cr_atan__fasttwosum(double x, double y, double *e){
  double s = x + y, z = s - x;
  *e = y - z;
  return s;
}

static inline double chelis_cr_atan__adddd(double xh, double xl, double ch, double cl, double *l) {
  double s = xh + ch, d = s - xh;
  *l = ((ch - d) + (xh + (d - s))) + (xl + cl);
  return s;
}

static inline double chelis_cr_atan__muldd_acc(double xh, double xl, double ch, double cl, double *l){
  double ahlh = ch*xl, alhh = cl*xh, ahhh = ch*xh, ahhl = __builtin_fma(ch, xh, -ahhh);
  ahhl += alhh + ahlh;
  return chelis_cr_atan__fasttwosum (ahhh, ahhl, l);
}

static double chelis_cr_atan__polydd(double xh, double xl, int n, const double chelis_cr_atan__c[][2], double *l){
  int i = n-1;
  double ch = chelis_cr_atan__c[i][0] + *l, cl = (chelis_cr_atan__c[i][0] - ch) + *l + chelis_cr_atan__c[i][1];
  while(--i>=0){
    ch = chelis_cr_atan__muldd_acc(xh,xl,ch,cl,&cl);
    double th = ch + chelis_cr_atan__c[i][0], tl = (chelis_cr_atan__c[i][0] - th) + ch;
    ch = th;
    cl += tl + chelis_cr_atan__c[i][1];
  }
  *l = cl;
  return ch;
}

