#include <stdint.h>

// Warning: clang also defines __GNUC__
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic ignored "-Wunknown-pragmas"
#endif


typedef uint64_t chelis_cr_tanh__u64;
typedef union {double f; chelis_cr_tanh__u64 u;} chelis_cr_tanh__b64u64_u;

static double chelis_cr_tanh__as_tanh_database(double, double);

static inline double chelis_cr_tanh__fasttwosum(double x, double y, double *e){
  double s = x + y, z = s - x;
  *e = y - z;
  return s;
}

static inline double chelis_cr_tanh__fasttwosub(double x, double y, double *e){
  double s = x - y, z = x - s;
  *e = z - y;
  return s;
}

static inline double chelis_cr_tanh__muldd_acc(double xh, double xl, double ch, double cl, double *l){
  double plh = xl*ch, phl = xh*cl, phh = xh*ch, phh_rest = __builtin_fma(xh, ch, -phh);
  phh_rest += (phl + plh);  
  return chelis_cr_tanh__fasttwosum(phh, phh_rest, l);
}

static inline double chelis_cr_tanh__mulddd_acc(double xh, double xl, double c, double *l){
  double pl = xl*c, ph = xh*c, ph_rest = __builtin_fma(xh, c, -ph);
  ph_rest += pl;
  return chelis_cr_tanh__fasttwosum(ph, ph_rest, l);
}

/* at input, l is the approximation of the upper part of the polynomial
   (evaluated with double arithmetic only) */
static inline double chelis_cr_tanh__polydd(double xh, double xl, int n, const double c[][2], double *l){
  int i = n-1;
  double ch, cl, t;
  ch = chelis_cr_tanh__fasttwosum(c[i][0], *l, &t);
  cl = t + c[i][1];
  // ch + cl ~= c[i][0] + c[i][1] + *l 
  while(--i>=0){
    ch = chelis_cr_tanh__muldd_acc(xh, xl, ch, cl, &cl);
    double th,tl;
    th = chelis_cr_tanh__fasttwosum(c[i][0], ch, &tl);
    ch = th;
    cl = (cl + c[i][1]) + tl;
  }
  *l = cl;
  return ch;
}

static double chelis_cr_tanh__as_exp_accurate(double x, double t, double th, double tl, double *l){
  static const double ch[][2] = {
    {0x1p+0, 0x1.6c16bd194535dp-94}, {0x1p-1, -0x1.8259d904fd34fp-93},
    {0x1.5555555555555p-3, 0x1.53e93e9f26e62p-57}};
  const double l2h = 0x1.62e42ffp-13, l2l = 0x1.718432a1b0e26p-47, l2ll = 0x1.9ff0342542fc3p-102;
  double dx = x - l2h*t, dxl = l2l*t, dxll = l2ll*t + __builtin_fma(l2l,t,-dxl);
  double dxh = dx + dxl; dxl = ((dx - dxh) + dxl) + dxll;
  double fl = dxh*(0x1.5555555555555p-5 + dxh *(0x1.11111113e93e9p-7 + dxh *0x1.6c16c169400a7p-10));
  double fh = chelis_cr_tanh__polydd(dxh,dxl,3,ch, &fl);
  fh = chelis_cr_tanh__muldd_acc(dxh,dxl,fh,fl,&fl);
  fh = chelis_cr_tanh__muldd_acc(th,tl,fh,fl,&fl);
  double zh = th + fh, zl = (th-zh) + fh;
  double uh = zh + tl, ul = ((zh-uh) + tl) + zl;
  double vh = uh + fl, vl = ((uh-vh) + fl) + ul;
  *l = vl;
  return vh;
}

static double chelis_cr_tanh__as_tanh_zero(double x){ // |x|<0.25
    static const double ch[][2] = {
        {-0x1.5555555555555p-2, -0x1.5555555554cc4p-56},
        {0x1.1111111111111p-3, 0x1.111110f8c0178p-59},
        {-0x1.ba1ba1ba1ba1cp-5, 0x1.7917c1d676ff5p-59},
        {0x1.664f4882c10fap-6, -0x1.9d5cb27c0af28p-63},
        {-0x1.226e355e6c23cp-7, -0x1.c9674586913f3p-61},
        {0x1.d6d3d0e157db3p-9, -0x1.71376fa06ce94p-65},
        {-0x1.7da36452b5e46p-10, -0x1.aba8d51bd9cp-65},
        {0x1.3558247faa32dp-11, -0x1.e0cfb423aedfdp-65},
        {-0x1.f57d76ea30928p-13, -0x1.c30601213cae9p-67},
    };
    static const double cl[] = {
        0x1.967e0a63ca836p-14,  -0x1.497b99d2a77d1p-15, 0x1.0ae346258cbdep-16,
        -0x1.aade68fb2f076p-18, 0x1.22e609bf8671fp-19,
    };
    double x2 = x * x, x2l = __builtin_fma(x, x, -x2);
    double y2 = x2 * (cl[0] + x2 * (cl[1] + x2 * (cl[2] + x2 * (cl[3] + x2 * cl[4]))));
    double y1 = chelis_cr_tanh__polydd(x2, x2l, 9, ch, &y2);
    y1 = chelis_cr_tanh__mulddd_acc(y1, y2, x, &y2);
    y1 = chelis_cr_tanh__muldd_acc(y1, y2, x2, x2l, &y2);
    double y0 = chelis_cr_tanh__fasttwosum(x, y1, &y1);
    y1 = chelis_cr_tanh__fasttwosum(y1, y2, &y2);
    chelis_cr_tanh__b64u64_u t = {.f = y1};
    if (__builtin_expect(!(t.u & (~0ul >> 12)), 0)) {
        chelis_cr_tanh__b64u64_u w = {.f = y2};
        if ((w.u ^ t.u) >> 63)
            t.u--;
        else
            t.u++;
        y1 = t.f;
        if (__builtin_fabs (x) == 0x1.ac343b179fec4p-3)
          return chelis_cr_tanh__as_tanh_database(x, y0 + y1);
    }
  return y0 + y1;
}

static double chelis_cr_tanh__as_tanh_database(double x, double f){
  static const double db[][3] = {
    {0x1.ac343b179fec4p-3, 0x1.a612499c53078p-3,  0x1p-57},
    {0x1.00764a988bf73p-2, 0x1.f676484c0703bp-3, -0x1p-104},
    {0x1.17d1e8a63711fp-2, 0x1.110e96a6c2d96p-2, -0x1p-105},
    {0x1.291c601a05276p-2, 0x1.210b7d0c03743p-2,  0x1p-56},
    {0x1.36f33d51c264dp-2, 0x1.2dbb7b1c91363p-2, -0x1p-106},
    {0x1.43eaea23649c3p-2, 0x1.39877ed028641p-2, -0x1p-55},
    {0x1.d88d7550b2826p-2, 0x1.b9a3637366afdp-2,  0x1p-56},
    {0x1.e611aa58ab608p-2, 0x1.c493dc899e4a6p-2, -0x1p-55},
    {0x1.01efe7ac8c15dp-1, 0x1.dc3fe1b524821p-2, -0x1p-104},
    {0x1.1005ec0bccabbp-1, 0x1.f20b1c8557dedp-2, -0x1p-55},
    {0x1.33dfeb0fa4bfep-1, 0x1.1372f9ee76e99p-1,  0x1p-55},
    {0x1.49f24ac5cac35p-1, 0x1.22c495ff06104p-1, -0x1p-104},
  };
  int a = 0, b = sizeof(db)/sizeof(db[0]) - 1, m = (a + b)/2;
  double ax = __builtin_fabs(x);
  while (a <= b) {
    if (db[m][0] < ax)
      a = m + 1;
    else if (db[m][0] == ax) {
      f = __builtin_copysign(1, x)*db[m][1] + __builtin_copysign(1, x)*db[m][2];
      break;
    } else
      b = m - 1;
    m = (a + b)/2;
  }
  return f;
}

